SELECT ws_bill_customer_sk, web_site_id, cd_credit_rating, total_quantity, last_order_date, quantity_rank, credit_category FROM ( SELECT ws_bill_customer_sk, web_site_id, cd_credit_rating, total_quantity, last_order_date, DENSE_RANK() OVER (ORDER BY total_quantity DESC) AS quantity_rank, CASE WHEN cd_credit_rating IN ('A','B') THEN 'Good' WHEN cd_credit_rating IN ('C','D') THEN 'Average' ELSE 'Poor' END AS credit_category FROM ( SELECT ws.ws_bill_customer_sk, ws_site.web_site_id, cd.cd_credit_rating, SUM(ws.ws_quantity) AS total_quantity, MAX(d_sold.d_date) AS last_order_date FROM web_sales ws JOIN date_dim d_sold ON ws.ws_sold_date_sk = d_sold.d_date_sk JOIN customer_demographics cd ON ws.ws_bill_cdemo_sk = cd.cd_demo_sk JOIN web_site ws_site ON ws.ws_web_site_sk = ws_site.web_site_sk GROUP BY ws.ws_bill_customer_sk, ws_site.web_site_id, cd.cd_credit_rating ) agg ) ranked_customers WHERE quantity_rank <= 10 ORDER BY quantity_rank, ws_bill_customer_sk
